function predictAge(features) {
    let score = XGB_MODEL.base;
    const n = XGB_MODEL.trees.length;
    for (let i = 0; i < n; i++) {
        const t = XGB_MODEL.trees[i];
        let node = 0;
        while (t.l[node] !== -1) {
            const fIdx = t.f[node];
            const val = features[fIdx] || 0;
            if (val < t.c[node]) {
                node = t.l[node];
            } else {
                node = t.r[node];
            }
        }
        score += t.w[node];
    }
    return Math.max(5.0, Math.min(21.9, score));
}

if (typeof window !== 'undefined') {
    window.XGB_MODEL = XGB_MODEL;
    window.predictAge = predictAge;
}
